mapper.select:
SELECT

FROM embed_channels

    deleted_at IS NULL

        AND id ILIKE CONCAT('%', #{param.id}, '%')


        AND tenant_id = #{param.tenantId}


        AND agent_id ILIKE CONCAT('%', #{param.agentId}, '%')


        AND name ILIKE CONCAT('%', #{param.name}, '%')


        AND enabled = #{param.enabled}


        AND publish_token ILIKE CONCAT('%', #{param.publishToken}, '%')


        AND allowed_origins ILIKE CONCAT('%', #{param.allowedOrigins}, '%')


        AND welcome_message ILIKE CONCAT('%', #{param.welcomeMessage}, '%')


        AND rate_limit_per_minute = #{param.rateLimitPerMinute}


        AND rate_limit_per_day = #{param.rateLimitPerDay}


        AND primary_color ILIKE CONCAT('%', #{param.primaryColor}, '%')


        AND page_title ILIKE CONCAT('%', #{param.pageTitle}, '%')


        AND header_title_mode ILIKE CONCAT('%', #{param.headerTitleMode}, '%')


        AND show_suggested_questions = #{param.showSuggestedQuestions}


        AND widget_position ILIKE CONCAT('%', #{param.widgetPosition}, '%')


        AND allow_web_search = #{param.allowWebSearch}


        AND allow_memory = #{param.allowMemory}


        AND allow_file_upload = #{param.allowFileUpload}


        AND default_locale ILIKE CONCAT('%', #{param.defaultLocale}, '%')


        AND webhook_url ILIKE CONCAT('%', #{param.webhookUrl}, '%')


        AND webhook_secret ILIKE CONCAT('%', #{param.webhookSecret}, '%')


        AND created_at = #{param.createdAt}


        AND updated_at = #{param.updatedAt}


        AND deleted_at = #{param.deletedAt}


ORDER BY id DESC
